use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── A: the chip-family layout contract — a cooperative tensor's
        // register layout is MEASURED per chip family (coop_layout), never
        // assumed inherited; the autotuner's refusal is the symptom, the
        // layout port is the fix.
        KernelRule {
            rule_id: "coop-tensor-layout-measured-per-chip-family".to_string(),
            gpu_concept: "MECHANISM (the per-chip-family cooperative-tensor layout contract; category A — memory access / register layout): a SIMD-group cooperative tensor's REGISTER LAYOUT is a hardware contract measured PER CHIP FAMILY (coop_layout), never assumed inherited from the previous generation — a cooperative matmul tile that fills its right operand and reads its destination in one family's layout computes WRONG PRODUCTS on the next, silently, and the autotuner keeping the tile off is the SYMPTOM (the defense working), not the fix. THE SOURCE LAW, verbatim (commit message): 'gemm_tile filled its right operand and read its destination in the M5 neural accelerators' register layout. The M3 and M4 GPUs (Apple9) lay a SIMD-group's cooperative tensors out as 8 x 8 matrices: a thread holds the reduction slots kr + 8*jj of the row pairs nc + e + 8*s (measured with coop_layout), so every product was wrong there and the autotuner kept the tile off, leaving every T > 1 projection on the shader GEMV — a DSpark verify of 8 rows at 8.8x a T = 1 pass, a prompt chunk at one pass per row.' THE MEASURED COST OF THE SYMPTOM: the correct refusal shipped as an 8.8x regression on every multi-token projection — a correct autotuner is not a correct pipeline. THE REPAIR PORTS THE LAYOUT, verbatim: 'With COOP_A9 (set by gemm_macros when the backend, or the device, is Apple9) the fill keeps its shape over twice the rows and half the columns — the reduction slots are permuted so that a thread's TK/8 slots of a row are TK/8 consecutive pack columns, which x_permute, perm_dest and x_permute_columns follow — and the epilogue reads the row pairs, with every fusion (residual, silu_mul, stat, norm and permute outputs, POST_NORM, the K-split). The row GEMVs that read x' outside a tile read four slots 8 apart. A 4-bit tile needs TK >= 128 on Apple9. The Apple10 source is unchanged, and the compiler passes that rewrite it still find their anchors.' — the layout family's three-port discipline: (1) the fill's slot permutation (the reduction slots kr + 8*jj read as TK/8 consecutive pack columns so the decode/pack machinery is UNCHANGED, only the addressing permutes); (2) every CONSUMER of the permuted x' follows (the row GEMVs' four-slots-8-apart reads, x_permute's inverse perm_dest); (3) the Apple10 arm UNCHANGED behind the COOP_A9 compile-time switch, with the in-family guards LOUD: '#if COOP_A9 && (TB2 || STAGE_B || SPLIT_K)' → '#error \"two token blocks, staged weights and the split fill assume the Apple10 cooperative layout\"' — the features that encode layout assumptions refuse to compile under the other family instead of silently misindexing. THE MEASURED WIN (commit message, 60-core M3 Ultra, source-reported): 'the tile takes NVFP4 at 8 rows from 8.80x to 2.50x a T = 1 pass (32 rows 5.81x), and the 27B's prefill of 43 tokens from 11.8 to 0.65 s.' THE MEASUREMENT INSTRUMENT IS THE LAW'S HALF: the layout was 'measured with coop_layout' (tests/kernels/test_gemm_tile.py) — the slot map is a device FACT read off the hardware, not a spec sheet claim. THE TEST DISCIPLINE: 'The tests of the Apple10-only paths built on that layout (static megakernel tasks, packed prefill operands, the fused draft program, the lm_head tile operand recipe, 4-bit tiles narrower than TK = 128) skip on Apple9 with the reason' — a layout-gated path declares its family and skips LOUD, never silently passes on the wrong hardware. DECISION CONTENT: (1) before running a cooperative tensor/cumulative-mma-style tile on a NEW chip family, MEASURE the register layout with the device's own introspection (a layout probe kernel) — never inherit the previous family's slot map; (2) a wrong-layout tile shows up as the AUTOTUNER refusing the tile (every candidate fails parity or correctness), and the cure is the layout port (slot permutation + consumer walk), not accepting the fallback; (3) the port keeps the FILL SHAPE (twice the rows, half the columns) and permutes SLOT ADDRESSES, so all downstream format/decode machinery survives unchanged; (4) in-family feature combos that assume the other layout get a compile-time #error, not a runtime surprise; (5) layout-gated test paths skip WITH THE REASON. REGIME: cooperative-tensor / warp-matrix tiles ported across GPU generations or families (Apple9↔Apple10, sm_70↔sm_80 mma fragments, RDNA encoder changes); any code holding a hardcoded lane→(row, column, slot) map for a hardware-managed operand. ANTI-REGIME: a layout the device documents as stable across the families in question (verify once, do not re-probe per build); software-managed layouts (a plain simdgroup shuffle the code owns end to end — remap freely); a tile the autotuner refuses for a MEASURED cost reason (the B223 two-knob law — tuning, not layout). NotBenchable here (the 8.80x→2.50x / 11.8→0.65 s figures are the source's M3 Ultra measurements — source-reported, provenance never a bar; the layout probe + the bit-identity of the permuted products are the exactness instruments). KINSHIP (do not double-count): mma-fragment-layout (B221 rider, entries_gpu_78) — the accumulator-IS-A-fragment layout COUPLING inside one architecture's ABI; THIS is the per-FAMILY layout CONTRACT across architectures (the same class one level up: a layout is a device fact, here measured per family); register-built-right-operand-lane-contiguous-plane-layout (ConvGemmLayout) — a software CHOICE of lane-contiguous plane layout for staging; THIS is the hardware-imposed map the software must discover; vendor-keyed-reduction-lane-partition-subgroup-request (B192) — a vendor-keyed PARTITION size, not a register slot map; B223's coherence-scope-by-write-set — buffer-granular coherence on the same repo, a different surface. Corpus greps (over src/domains/kernel_opt/corpus/): 'cooperative tensor' — consumer prose only (entries_gpu_09 Metal tensorops staging, gpu_60/gpu_66 decode-into-registers), no layout-contract owner; 'coop_layout' — zero; 'Apple9/Apple10' — zero; '8 x 8 matrices' — zero; 'chip famil*' — prose senses only (entries_gpu_48/66/71/85 device-family rows), no slot-map owner. CITE: lithos-ai/lithos-metal @ 7781e9341e7f43a1d393e506d6d1431e692b81fd (#35, Apache-2.0, merged 2026-10-12) -- kernels/common/gemm_tile.metal (the COOP_A9 arms: the CT/ROWS_T/C_CAP macro forks, the kr/nc lane decode, the #error guard, the Apple9 fill loop), kernels/common/gemv_bf16_rows.metal + gemv_bf16_small.metal + gemv_nvfp4_rows.metal (the xperm_slot four-slots-8-apart reads), monolith/kernels.py (PERM_A9 x_permute/perm_dest plumbing), tests/contract/test_gemm_layouts.py, commit message (the law + the measurements). Batch 227 / Plan 229 / Research 257.".to_string(),
            ref_shape: "// naive: the cooperative matmul tile hardcodes the M5 (Apple10)\n// register layout - a thread's reduction slots and destination rows\n// read as consecutive quads - and runs it on Apple9, where the\n// hardware lays cooperative tensors out as 8x8 matrices. Every\n// product is wrong; the parity check fails for every candidate; the\n// autotuner keeps the tile OFF and every multi-token projection\n// falls back to the per-row shader GEMV (8.8x a T=1 pass).\nconst CT: usize = TK / 4; // a thread's consecutive columns (a quad)\nconst NS_B: usize = TN / 8; // row slots per thread\n\nfn fill_right_operand(w: &[u32], lane: u32) -> Tile {\n    let c1b = ((lane >> 1) & 3) + 4 * ((lane >> 4) & 1); // row-slot base\n    let mut t = Tile::zeroed();\n    for s in 0..NS_B {\n        let n = c1b + 8 * s as u32; // row inside the tile (Apple10 map)\n        let word = w[word_index(n, c1b)]; // consecutive columns\n        t.set(n, c1b, decode(word)); // WRONG on Apple9: the hardware\n    } // holds slots kr + 8*jj of row PAIRS\n    t\n}\n\n// the destination is read back through the same wrong map, so even a\n// correct fill would misplace the epilogue reads.\nfn epilogue(t: &Tile, out: &mut [f32]) {\n    for i in 0..t.capacity() {\n        out[dest_index(i)] = t[i]; // Apple10 order\n    }\n}".to_string(),
            opt_pattern: "// optimized: COOP_A9 - the fill keeps its shape over TWICE the\n// rows and HALF the columns; the reduction slots are permuted so a\n// thread's TK/8 slots of a row are TK/8 consecutive pack columns\n// (the decode/pack machinery is unchanged - only addressing\n// permutes), the epilogue reads the row pairs, the row GEMVs that\n// read x' outside a tile read four slots 8 apart, and the Apple10\n// combos that assume the other layout get a compile-time error.\nconst CT: usize = TK / 8; // a thread's consecutive columns (an eighth)\nconst ROWS_T: usize = 2 * (TN / 8); // rows per thread (pairs)\n\nfn fill_right_operand_a9(w: &[u32], lane: u32) -> Tile {\n    let kr = ((lane >> 1) & 3) + 4 * ((lane >> 4) & 1); // slots kr + 8*jj\n    let nc = 2 * (lane & 1) + 4 * ((lane >> 3) & 1); // rows nc + e + 8*s\n    let mut t = Tile::zeroed();\n    for rr in 0..ROWS_T {\n        let (s, e) = (rr >> 1, rr & 1);\n        let n = nc + e as u32 + 8 * s as u32; // pairs of adjacent rows\n        let c0 = CT as u32 * kr; // this thread's first tile column\n        let word = w[word_index(n, c0)]; // CT consecutive pack columns\n        t.set(n, c0, decode(word)); // the SAME slots the hardware holds\n    }\n    t\n}\n\n// the layout probe is the law's instrument: measure the slot map with\n// the device's own introspection (coop_layout) per chip family\n// before trusting any inherited map.\nfn epilogue_a9(t: &Tile, out: &mut [f32]) {\n    for i in 0..t.capacity() {\n        out[dest_index_pairs(i)] = t[i]; // reads the row pairs\n    }\n}".to_string(),
        },
        // ── D: the N-exact reproduction law — a shape-dependent chunk
        // parameter breaks exact-pass promises; rows take their sub-pass's
        // chunking, chunks are boundary multiples, and the variant clone
        // admits only whole fold-chains.
        KernelRule {
            rule_id: "exact-pass-rows-take-their-sub-pass-chunking".to_string(),
            gpu_concept: "MECHANISM (the N-exact reproduction contract under pass-shape variation; category D — dispatch admission + bit-identity): a kernel family promising N-exact (bit-identical) results across pass shapes MUST NOT let any scheduling parameter DERIVED FROM THE PASS SHAPE (a chunk width sized from the pass's context) leak into a row's reduction order — the promise is broken silently, and the repair restores each row's parameters from the sub-pass shape it belongs to, never from the enclosing pass. THE SOURCE LAW, verbatim (commit message): 'pick_chunk sizes the attention's key chunks from the pass's context, so a 512-row prompt pass summed a row's keys in a different order than the 128-row pass N-exact promises to reproduce. Rows of an exact pass now take the chunking of the 128-row pass they belong to (EXACT_SUB).' THE IN-KERNEL CONTRACT, verbatim (gqa_decode.metal): 'A prompt pass of T rows reproducing passes of EXACT_SUB rows: the rows of each such sub-pass take the chunking that sub-pass would (pick_chunk of its own context), so every row sums its keys in that pass's order. The blocks of the sub-passes follow one another; s0 is a block's first token and sub-pass s0 appends keys from qpos0 + s0.' — THREE faces: (1) the CORE: per-sub-pass chunking (each row's pick_chunk uses its sub-pass's context, `cs = qpos0 + s1`), and the CACHE-APPEND GUARD ('rg == 0' becomes 'rg == 0 && key >= qpos0 + s0') — without it every sub-pass re-appends the shared prefix keys to the caches; (2) the MERGE follows: 'const uint ctx_t = ctx - T + min((t / EXACT_SUB + 1u) * EXACT_SUB, T);' — the partials merge's chunking is PER ROW ('the context of the row's EXACT_SUB-row pass'), not the enclosing pass's; (3) the BOUNDARY LAW (the follow-up commit): a large exact chunk must be a MULTIPLE of the sub-pass size — verbatim: 'The large pass reproduces the 128-row passes it is made of, so it has to start and end on their boundaries; a 192-row chunk would put rows 128-191 of a 384-token prompt in a sub-pass of the wrong context.' — enforced as a LOUD config refusal: 'raise ValueError(f\\\"an exact prefill chunk is a multiple of {self.EXACT_ROWS} rows, got {prefill_chunk_size}\\\")'. THE ADMISSION (the compiler half, verbatim docstring): 'Make a prompt program's attention reproduce passes of ``rows`` rows bit for bit: the run-time chunk rule (``pick_chunk``) depends on the pass's context, so the cores and folds of the chunked attention take each row's chunking from the ``rows``-row pass that row would be in (``EXACT_SUB``). Fixed-chunk kernels (v2, the matrix attention) already sum every row the same way; a workspace shared with any other core is left alone.' — the EXACT_SUB variant is CLONED per rows ('kernel.macros['EXACT_SUB'] = f'{rows}u'') and admitted ONLY when the whole fold-chain is chunked (the chunked() predicate: STEP_STATE=1 and no DRAFT/LM_MODE/STEAL/FIXED_CHUNK/ADAPTIVE_CHUNK on BOTH the decode cores AND their gqa_merge folds — a mixed chain stays uncloned: a fixed-chunk kernel mixed with a chunked one reproduces nothing and the clone would just fork the binary). THE SERVING POSTURE (the third commit, verbatim): '512-row exact passes (the 128-row results bit for bit): a 2846-token Qwen3.8-27B prompt's first token 9.2 -> 8.6 s with the measured kernel choices; 1024 rows measured no better.' — the exact pass BUYS throughput (fewer pass launches) at equal bits, and the plateau is measured, not assumed. DECISION CONTENT: (1) audit every scheduling parameter for PASS-SHAPE dependence when a kernel promises shape-exact reproduction — chunk widths, block counts, partition sizes derived from context/batch are the silent breakers; (2) the repair is PER-ROW PARAMETER RESTORATION (each row uses the parameters of the sub-pass shape that row belongs to), not a global re-tune; (3) side-effecting prologue work (cache appends) needs the sub-pass-ownership guard or sub-passes double-append; (4) the merge/partial-reduction half must restore parameters with the SAME sub-pass granularity as the core (per-row ctx_t), or the fold reorders what the core preserved; (5) exact chunks are boundary multiples of the sub-pass size — enforce at CONFIG time with a loud refusal naming the multiple; (6) the variant clone admits only whole fold-chains whose every member is actually chunked. REGIME: exact-reproduction serving modes (draft-verify anchors, replay/parity gates, A/B bit-identity contracts) over chunked reductions whose scheduling derives from the pass shape; batch-size-flexible prefill promising per-row equality with the single-row pass. ANTI-REGIME: kernels whose reduction order is order-independent BY CONSTRUCTION (fixed-chunk, matrix attention — the source's own carve-out: 'Fixed-chunk kernels (v2, the matrix attention) already sum every row the same way'); batch-composition invariance owned at the grid level (batch-composition-invariant-grid-early-return — per-row arithmetic isolated from batchmates BY the early return; compose: that rule makes rows independent of BATCHMATES, this rule makes rows independent of the PASS SHAPE's derived parameters — different axes, a kernel can need both); a client merely TOLERATING reordering (no exactness contract — pick_chunk freely). NotBenchable here (the 9.2→8.6 s figure is the source's M3 Ultra serving measurement — source-reported, provenance never a bar; the bit-for-bit test contract is the exactness instrument). KINSHIP (do not double-count): batch-composition-invariant-grid-early-return (entries_gpu_14) — per-row arithmetic INCLUDING float summation order bit-identical regardless of batchmates, BY CONSTRUCTION via the grid; THIS repairs a broken promise by restoring per-row parameters (the derived-parameter face; that rule's grid-level early return is the construction-level face — the two compose); wide-verify-warp-specialized-scores-in-registers-pv (entries_gpu_48) — order-KEEPING inside one kernel's arms ('Row sums keep the two 32-key halves and their order'); verified-logits-derived-outputs-path-independence (B215) — logprob rows read the VERIFIED logits so outputs are path-independent by construction; dispatch-cliff-bitexact-shape-confinement (B115) — confines a fast path to shapes where it is BIT-EXACT (refusal, not restoration); splitk-reduce-one-launch-slice-order-pinned (B199) — pins a fused reduction's order to the loop it replaces (same order-preservation class, different hazard: fused-vs-loop, not shape-derived parameters). Corpus greps (over src/domains/kernel_opt/corpus/): 'pick_chunk' — zero; 'sub-pass/subpass' — zero; 'N-exact' — zero; 'exact pass' — zero; chunk-width-from-context owners — none (VarlenChunkedReduction's five rules pad/split chunks for WORK shape, never for order contracts). CITE: lithos-ai/lithos-metal @ 087db24 ('attention: exact large prompt passes keep each row's chunking') + 182d016 ('serve: an exact prompt chunk above 128 rows is a multiple of 128') + 4effa4a ('backends: 512-row exact prompt passes on the M3 Ultra'), all Apache-2.0 (PR #36, merged 2026-10-12) -- kernels/common/gqa_decode.metal (the EXACT_SUB arm + exact_sub_blocks + the append guard), kernels/common/gqa_common.metal (the helper), monolith/compiler/prefill.py (exact_attention: the chunked() predicate + the per-rows kernel clone), monolith/generate.py + monolith/serve.py (the multiple-of refusal), monolith/backends/metal/m3_ultra_60c/backend.py (serving_prefill_chunk = 512), tests/contract/test_prefill.py + tests/kernels/test_gqa_decode.py, commit messages. Batch 227 / Plan 229 / Research 257.".to_string(),
            ref_shape: "// naive: the exact prefill pass reuses the SAME kernel with the\n// SAME context-derived chunk rule — pick_chunk(context of the whole\n// pass) — so a 512-row pass chunks keys differently than the 128-row\n// passes it promises to reproduce, and a row's keys are summed in a\n// different ORDER: the N-exact contract is silently broken.\nfn pick_chunk(ctx: u32, kv_heads: u32, rep: u32, n_sg: u32, max: u32) -> u32 {\n    // chunk width grows with the pass's context\n    min((ctx / n_sg).next_power_of_two() / 2, max)\n}\n\nfn gqa_decode(qkvg: &[u16], ctx: u32, t_rows: u32) {\n    let ch = pick_chunk(ctx, KV_HEADS, REP, N_SG, N_CHUNKS_MAX); // WHOLE pass\n    let n_chunks = (ctx + ch - 1) / ch;\n    for b in block_iter(n_chunks, t_rows) {\n        let (k0, k1) = chunk_bounds(b, ch, ctx);\n        sum_keys(qkvg, k0, k1); // 512-row pass: ch = 256\n    } // 128-row pass: ch = 64 — DIFFERENT order per key\n}\n\n// the merge reads partials under the WHOLE pass's chunking too:\nfn gqa_merge(part: &[f32], ctx: u32, row: u32) -> f32 {\n    let ch = pick_chunk(ctx, KV_HEADS, REP, N_SG, N_CHUNKS_MAX);\n    fold(part, (ctx + ch - 1) / ch) // wrong granularity per row\n}".to_string(),
            opt_pattern: "// optimized: EXACT_SUB — every row takes the chunking of the\n// sub-pass it belongs to (its own context), the cache-append guard\n// scopes to the sub-pass's own keys, the merge uses the row's\n// sub-pass context, and an exact chunk is a MULTIPLE of EXACT_SUB\n// (config refuses otherwise, loud).\nfn exact_sub_blocks(qpos0: u32, s0: u32, t: u32) -> u32 {\n    // blocks of sub-pass s0 (its own context qpos0 + s0 + EXACT_SUB)\n    let cs = qpos0 + min(s0 + EXACT_SUB, t);\n    let chs = pick_chunk(cs, KV_HEADS, REP, N_SG, N_CHUNKS_MAX);\n    let ncs = (cs + chs - 1) / chs;\n    let nrs = (REP * (min(s0 + EXACT_SUB, t) - s0) + RBMAX - 1) / RBMAX;\n    KV_HEADS * ncs * nrs\n}\n\nfn gqa_decode_exact(qkvg: &[u16], qpos0: u32, t_rows: u32) {\n    // locate the owning sub-pass, then ITS chunking:\n    let (b, s0) = locate(bx, qpos0, t_rows); // walks exact_sub_blocks\n    let s1 = min(s0 + EXACT_SUB, t_rows);\n    let cs = qpos0 + s1;\n    let chs = pick_chunk(cs, KV_HEADS, REP, N_SG, N_CHUNKS_MAX); // sub-pass ctx\n    let (k0, k1) = chunk_bounds(b, chs, cs);\n    sum_keys(qkvg, k0, k1); // the 128-row pass's order, every row\n    if rg == 0 && key >= qpos0 + s0 {\n        append_cache(key); // only THIS sub-pass's keys, once\n    }\n}\n\nfn gqa_merge_exact(part: &[f32], ctx: u32, t_total: u32, row: u32) -> f32 {\n    let ctx_t = ctx - t_total + min((row / EXACT_SUB + 1) * EXACT_SUB, t_total);\n    let ch = pick_chunk(ctx_t, KV_HEADS, REP, N_SG, N_CHUNKS_MAX); // per-row\n    fold(part, (ctx_t + ch - 1) / ch)\n}\n\n// config-time boundary law:\nif prefill_exact && prefill_chunk_size % EXACT_ROWS != 0 {\n    panic!(\"an exact prefill chunk is a multiple of {EXACT_ROWS} rows, got {prefill_chunk_size}\");\n}".to_string(),
        },
    ]
}
